    /**
     * The builder of headers' name for the gRPC component.
     */
    public static class GrpcHeaderNameBuilder {
        /**
         * The internal instance of the builder used to access to all the
         * methods representing the name of headers.
         */
        public static final GrpcHeaderNameBuilder INSTANCE = new GrpcHeaderNameBuilder();

        /**
         * The name of the method that the client called, as the Java method
         * name in lowerCamelCase, for example sendPing. The consumer sets it.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: consumer
         * 
         * @return the name of the header {@code GrpcMethodName}.
         */
        public String grpcMethodName() {
            return "CamelGrpcMethodName";
        }
        /**
         * The user agent of the client that made the call, from the user-agent
         * header of the request. The consumer sets it.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: consumer
         * 
         * @return the name of the header {@code GrpcUserAgent}.
         */
        public String grpcUserAgent() {
            return "CamelGrpcUserAgent";
        }
        /**
         * The event of the stream: onNext for a message, onCompleted when the
         * stream completes, or onError when it fails. The consumer sets it for
         * client and bidirectional streaming calls, and the producer on the
         * exchanges that it sends to streamRepliesTo. The STREAMING producer
         * and a producer with toRouteControlledStreamObserver read it to select
         * the event to send.
         * 
         * The option is a: {@code String} type.
         * 
         * Group: consumer
         * 
         * @return the name of the header {@code GrpcEventType}.
         */
        public String grpcEventType() {
            return "CamelGrpcEventType";
        }
    }
    static GrpcEndpointBuilder endpointBuilder(String componentName, String path) {
        class GrpcEndpointBuilderImpl extends AbstractEndpointBuilder implements GrpcEndpointBuilder, AdvancedGrpcEndpointBuilder {
            public GrpcEndpointBuilderImpl(String path) {
                super(componentName, path);
            }
        }
        return new GrpcEndpointBuilderImpl(path);
    }
